package com.medtrack.tracking.entity; import com.medtrack.shipment.entity.Shipment; import com.medtrack.user.entity.User; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="tracking_events") public class TrackingEvent {@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="shipment_id",nullable=false)private Shipment shipment;@Enumerated(EnumType.STRING)@Column(name="milestone_status",nullable=false)private MilestoneStatus milestoneStatus;@Column(name="location_name",nullable=false)private String locationName;private Double latitude;private Double longitude;private String remarks;@Column(name="event_timestamp",nullable=false)private Instant eventTimestamp;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="created_by",nullable=false)private User createdBy;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();protected TrackingEvent(){}public TrackingEvent(Shipment s,MilestoneStatus m,String l,Double lat,Double lon,String r,Instant t,User u){shipment=s;milestoneStatus=m;locationName=l;latitude=lat;longitude=lon;remarks=r;eventTimestamp=t;createdBy=u;}public MilestoneStatus getMilestoneStatus(){return milestoneStatus;}public String getLocationName(){return locationName;}public Double getLatitude(){return latitude;}public Double getLongitude(){return longitude;}public String getRemarks(){return remarks;}public Instant getEventTimestamp(){return eventTimestamp;}}
